  "implementation": "def solve(case):
    word_token_indices = case['word_token_indices']
    word_labels = case['word_labels']
    token_count = case['token_count']

    # Validate lengths
    if len(word_token_indices) != len(word_labels):
        raise ValueError("Number of word groups and labels must match")

    # Initialize token_labels with None
    token_labels = [None] * token_count
    seen = set()

    # Process each group
    for indices, label in zip(word_token_indices, word_labels):
        if not indices:
            continue  # empty group? could happen, but according to data groups have at least one token
        for idx in indices:
            if not isinstance(idx, int) or idx < 0 or idx >= token_count:
                raise ValueError(f"Token index {idx} out of range [0, {token_count-1}]")
            if idx in seen:
                raise ValueError(f"Duplicate token index {idx}")
            seen.add(idx)
            token_labels[idx] = label

    # Check coverage
    if len(seen) != token_count:
        missing = [i for i in range(token_count) if i not in seen]
        raise ValueError(f"Uncovered token indices: {missing}")

    # Build kept_indices
    kept_indices = [i for i, lab in enumerate(token_labels) if lab == 1]

    return {
        'kept_indices': kept_indices,
        'token_labels': token_labels
    }"
}
